API_VERSION = "2026-03-10"
MAX_SUBTASKS = 20
MAX_ISSUE_TITLE_LENGTH = 120
MAX_TASK_TITLE_LENGTH = 120
MAX_TEXT_FIELD_LENGTH = 5000

AF_EPIC_RE = re.compile(r"^AF-E-\d{4}$")
AF_ID_PART_RE = re.compile(r"^AF-E-(\d{4})$")
AF_ID_IN_TITLE_RE = re.compile(r"^\[(AF-E-\d{4})\]\s*(.+)$")
AF_IDEA_RE = re.compile(r"^AF-I-\d{4}$")
TASK_ID_RE = re.compile(r"^\[(AF-T-\d{4}\.\d+)\]")
GENERATED_MARKER_RE = re.compile(r"<!--\s*roadmap-automation:\s*generated=true\s+af_id=(AF-E-\d{4})\s*-->")

